package thaumcraft.verification;

import java.util.*;
import java.util.function.BiConsumer;
import java.nio.file.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.Difficulty;
import net.minecraft.world.effect.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.animal.Cow;
import net.minecraft.world.entity.item.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.*;
import thaumcraft.blocks.*;
import thaumcraft.entities.*;
import thaumcraft.registry.*;
import thaumcraft.world.dim.OuterChunkGenerator;

final class OuterFoundationVerification {
    private static final BlockPos POS=new BlockPos(3368,145,80);
    static final ResourceKey<Level> OUTER=ResourceKey.create(Registries.DIMENSION,ResourceLocation.parse("thaumcraft:outer_lands"));
    static void run(ServerLevel level,BiConsumer<Boolean,String> check)throws Exception {
        try{
            var outer=level.getServer().getLevel(OUTER);check.accept(outer!=null&&outer.getChunkSource().getGenerator() instanceof OuterChunkGenerator,"actual server creates Outer Lands with its own registered ChunkGenerator");
            var type=outer.dimensionType();check.accept(outer.getMinBuildHeight()==0&&outer.getMaxBuildHeight()==128&&!type.hasSkyLight()&&type.hasCeiling(),"native dimension has original air range0..127 and no skylight");check.accept(type.hasFixedTime()&&!type.bedWorks()&&!type.respawnAnchorWorks()&&!type.natural()&&outer.getTimeOfDay(0)==0,"original constant time angle0 and no respawn dimension");
            var biome=outer.getBiome(new BlockPos(-23,50,37));check.accept(biome.is(ResourceLocation.parse("thaumcraft:eldritch"))&&!biome.value().hasPrecipitation()&&biome.value().getSkyColor()==0,"native fixed eldritch biome has no weather and black sky");
            var monsters=biome.value().getMobSettings().getMobs(MobCategory.MONSTER).unwrap();check.accept(monsters.size()==2&&monsters.stream().allMatch(e->e.getWeight().asInt()==1&&e.minCount==1&&e.maxCount==1)&&monsters.stream().anyMatch(e->e.type==R5Entities.INHABITED_ZOMBIE.get())&&monsters.stream().anyMatch(e->e.type==R2Entities.ELDRITCH_GUARDIAN.get()),"original biome spawns actual inhabited zombie and guardian, weight1 group1");
            for(var category:MobCategory.values())if(category!=MobCategory.MONSTER)check.accept(biome.value().getMobSettings().getMobs(category).isEmpty(),"original eldritch biome clears "+category+" spawn list");
            for(var cp:List.of(new ChunkPos(2,3),new ChunkPos(-3,-2))){var chunk=outer.getChunk(cp.x,cp.z);boolean empty=true;for(int x=0;x<16;x++)for(int y=0;y<128;y++)for(int z=0;z<16;z++)empty&=chunk.getBlockState(new BlockPos(cp.getMinBlockX()+x,y,cp.getMinBlockZ()+z)).isAir();check.accept(empty,"fully generated native chunk remains original void before labyrinth assignment: "+cp);}
            level.getEntitiesOfClass(Entity.class,new AABB(POS).inflate(30)).forEach(Entity::discard);
            for(var block:List.of(R5Content.OBELISK.get(),R5Content.ELDRITCH_CAP.get())){var state=block.defaultBlockState();level.setBlock(POS,state,2);check.accept(state.getDestroySpeed(level,POS)==50&&block.getExplosionResistance()==12000&&state.getLightEmission(level,POS)==8&&!state.isSolidRender(level,POS),"original obelisk/cap hardness50 effective blast resistance12000 light8 nonopaque");check.accept(state.getCollisionShape(level,POS).bounds().equals(new AABB(0,0,0,1,1,1))&&Block.getDrops(state,level,POS,level.getBlockEntity(POS)).isEmpty(),"original obelisk/cap retain full collision and no drops");}
            check.accept(R5Content.ELDRITCH_CAP.get().getTicker(level,R5Content.ELDRITCH_CAP.get().defaultBlockState(),R5Content.CAP_ENTITY.get())==null,"original cap is a non-ticking tile");
            level.setBlock(POS,R5Content.OBELISK.get().defaultBlockState(),2);var tile=(EldritchObeliskBlockEntity)level.getBlockEntity(POS);check.accept(tile.renderBounds().getYsize()==5,"obelisk render bounds include its floating five-block model");
            var guardian=R2Entities.ELDRITCH_GUARDIAN.get().create(level);guardian.moveTo(POS.getX()+6,POS.getY(),POS.getZ()+6,0,0);guardian.setNoAi(true);level.addFreshEntity(guardian);var crab=R5Entities.CRAB.get().create(level);crab.moveTo(POS.getCenter());level.addFreshEntity(crab);
            EldritchObeliskBlockEntity.tick(level,POS,tile.getBlockState(),tile);check.accept(guardian.hasEffect(MobEffects.DAMAGE_BOOST)&&!guardian.hasEffect(MobEffects.REGENERATION),"original undead guardian receives strength but rejects regeneration, even at AABB corner outside radius6");check.accept(!crab.hasEffect(MobEffects.REGENERATION)&&!crab.hasEffect(MobEffects.DAMAGE_BOOST),"original marker filter excludes eldritch crab");guardian.discard();guardian=null;var marked=new MarkedCow(level);marked.moveTo(POS.getX()+6,POS.getY(),POS.getZ()+6,0,0);level.addFreshEntity(marked);EldritchObeliskBlockEntity.tick(level,POS,tile.getBlockState(),tile);check.accept(marked.hasEffect(MobEffects.REGENERATION)&&marked.getEffect(MobEffects.REGENERATION).getDuration()==40&&marked.getEffect(MobEffects.REGENERATION).isAmbient(),"original duration40 ambient effect applies to native living API marker");
            marked.removeEffect(MobEffects.DAMAGE_BOOST);EldritchObeliskBlockEntity.tick(level,POS,tile.getBlockState(),tile);check.accept(!marked.hasEffect(MobEffects.DAMAGE_BOOST),"regeneration suppresses reapplication of both obelisk effects");marked.removeEffect(MobEffects.REGENERATION);EldritchObeliskBlockEntity.tick(level,POS,tile.getBlockState(),tile);check.accept(marked.hasEffect(MobEffects.DAMAGE_BOOST),"original non-incremented counter reapplies on next tick without a20tick delay");marked.removeAllEffects();marked.moveTo(POS.getX()+8,POS.getY(),POS.getZ());EldritchObeliskBlockEntity.tick(level,POS,tile.getBlockState(),tile);check.accept(!marked.hasEffect(MobEffects.REGENERATION),"marked beyond AABB boundary receives no obelisk effects");marked.discard();crab.discard();
            var previousDifficulty=level.getDifficulty();try{for(var difficulty:List.of(Difficulty.NORMAL,Difficulty.HARD)){level.getServer().setDifficulty(difficulty,true);for(int seed=0;seed<12;seed++){var zombie=R5Entities.INHABITED_ZOMBIE.get().create(level);zombie.getRandom().setSeed(seed);zombie.moveTo(POS.getCenter());var random=net.minecraft.util.RandomSource.create(seed);float chance=difficulty==Difficulty.HARD?.9f:.6f;boolean chest=random.nextFloat()<=chance,legs=random.nextFloat()<=chance;var data=new SpawnGroupData(){};check.accept(zombie.finalizeSpawn(level,level.getCurrentDifficultyAt(POS),MobSpawnType.MOB_SUMMONED,data)==data&&!zombie.isBaby(),"original inhabited spawn does not invoke vanilla baby/jockey initialization");check.accept(zombie.getItemBySlot(EquipmentSlot.HEAD).is(R5Content.CULTIST_ARMOR.get("cultist_plate_helmet").get())&&zombie.getItemBySlot(EquipmentSlot.CHEST).isEmpty()!=chest&&zombie.getItemBySlot(EquipmentSlot.LEGS).isEmpty()!=legs,"original inhabited armor probability and RNG ordering "+difficulty+" seed"+seed);check.accept(zombie.getMaxHealth()==30&&zombie.getAttributeValue(Attributes.ATTACK_DAMAGE)==5&&zombie.getAttributeValue(Attributes.SPAWN_REINFORCEMENTS_CHANCE)==0,"inhabited zombie native original attributes");zombie.discard();}}}finally{level.getServer().setDifficulty(previousDifficulty,true);}
            var zombie=R5Entities.INHABITED_ZOMBIE.get().create(level);zombie.moveTo(POS.getCenter().add(3,0,0));zombie.setNoAi(true);level.addFreshEntity(zombie);check.accept(!zombie.killedEntity(level,new Cow(EntityType.COW,level)),"inhabited host has no vanilla villager-conversion path");var start=zombie.position();float eye=zombie.getEyeHeight();zombie.hurt(level.damageSources().magic(),1000);check.accept(zombie.getHealth()==0&&!zombie.isRemoved(),"original inhabited death callback defers transformation to death tick");zombie.tick();var emerged=level.getEntitiesOfClass(EldritchCrab.class,new AABB(start,start).inflate(4));check.accept(zombie.isRemoved()&&emerged.size()==1&&emerged.getFirst().hasHelm(),"first death tick removes host and spawns exactly one real armored crab");check.accept(emerged.getFirst().position().distanceTo(start.add(0,eye,0))<1e-6,"crab emerges at original host eye height");check.accept(level.getEntitiesOfClass(ItemEntity.class,new AABB(start,start).inflate(4)).isEmpty(),"inhabited death drops no vanilla rotten flesh or equipped armor");emerged.forEach(Entity::discard);
            riderOracle(level,check);
            outer.setBlock(new BlockPos(31,50,-31),R5Content.ELDRITCH_CAP.get().defaultBlockState(),2);
        }finally{OuterRuntimeVerification.releaseChunks(level);}
    }
    private static void riderOracle(ServerLevel level,BiConsumer<Boolean,String> check)throws Exception{
        var controls=com.google.gson.JsonParser.parseString(Files.readString(Path.of(System.getProperty("thaumcraft.r3.root"),"analysis/full_port/original-rider-positions.json"))).getAsJsonArray();check.accept(controls.size()==56,"all56 controls were obtained from unchanged original1.7.10 rider bytecode");
        for(var entry:controls){var scene=entry.getAsJsonObject();double x=scene.get("x").getAsDouble();var origin=BlockPos.containing(x,146,x);var snapshots=new HashMap<BlockPos,net.minecraft.world.level.block.state.BlockState>();
            try{for(int dx=-5;dx<=5;dx++)for(int dy=-2;dy<=3;dy++)for(int dz=-5;dz<=5;dz++){var pos=origin.offset(dx,dy,dz);snapshots.put(pos,level.getBlockState(pos));level.setBlock(pos,Blocks.AIR.defaultBlockState(),2);}for(var value:scene.getAsJsonArray("blocks")){var b=value.getAsJsonArray();int kind=b.get(3).getAsInt();var state=kind==1?Blocks.STONE.defaultBlockState():kind==2?Blocks.WATER.defaultBlockState():Blocks.OAK_LEAVES.defaultBlockState().setValue(LeavesBlock.PERSISTENT,true);level.setBlock(new BlockPos(b.get(0).getAsInt(),b.get(1).getAsInt(),b.get(2).getAsInt()),state,2);}var rider=R5Entities.CRAB.get().create(level);rider.moveTo(x,146,x,0,0);var mount=new Cow(EntityType.COW,level);mount.moveTo(x+3,144,x-2,0,0);var e=scene.getAsJsonArray("expected");var expected=new Vec3(e.get(0).getAsDouble(),e.get(1).getAsDouble(),e.get(2).getAsDouble());var actual=LegacyRiderPosition.choose(rider,mount);check.accept(actual.distanceTo(expected)<1e-6,"native position matches original rider bytecode x"+x+" scene"+scene.get("scene")+" expected"+expected+" actual"+actual);rider.discard();mount.discard();}finally{snapshots.forEach((p,s)->level.setBlock(p,s,2));}}
    }
    static void reload(ServerLevel level,BiConsumer<Boolean,String> check){var outer=level.getServer().getLevel(OUTER);check.accept(outer!=null&&outer.getChunkSource().getGenerator() instanceof OuterChunkGenerator,"own generator dimension survives actual server restart");var pos=new BlockPos(31,50,-31);check.accept(outer.getBlockState(pos).is(R5Content.ELDRITCH_CAP.get())&&outer.getBlockEntity(pos) instanceof EldritchCapBlockEntity,"native Outer Lands chunk and tile survive actual server restart");check.accept(outer.getBiome(pos).is(ResourceLocation.parse("thaumcraft:eldritch")),"native fixed biome survives actual server restart");OuterRuntimeVerification.releaseChunks(level);}
    private static final class MarkedCow extends Cow implements thaumcraft.api.entities.IEldritchMob {MarkedCow(Level level){super(EntityType.COW,level);setNoAi(true);}}
    private OuterFoundationVerification(){}
}
